+/// Origin rail for a session-projection frame.
+#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
+#[serde(rename_all = "snake_case")]
+pub enum SessionProjectionSource {
+    Agent,
+    Control,
+}
+
+/// One ordered, session-scoped projection frame. `event` retains the existing
+/// agent/control payload shape so legacy reducers can be reused without a
+/// second transcript event vocabulary.
+#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
+pub struct SessionProjectionFrame {
+    pub cursor: String,
+    pub source: SessionProjectionSource,
+    pub event: Value,
+}
+
+/// Folded state that is not fully represented by persisted provider history.
+#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, Default)]
+pub struct SessionProjectionState {
+    #[serde(default, skip_serializing_if = "Option::is_none")]
+    pub active_turn: Option<Value>,
+    #[serde(default, skip_serializing_if = "Option::is_none")]
+    pub last_turn_finished: Option<Value>,
+    #[serde(default)]
+    pub pending_permissions: Vec<Value>,
+    #[serde(default)]
+    pub components: Vec<Value>,
+    #[serde(default)]
+    pub browser_active: bool,
+}
+
+/// Atomic session snapshot watermark and the retained frames not yet subsumed
+/// by the matching persisted session revision.
+#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
+pub struct SessionProjection {
+    pub version: u32,
+    pub cursor: String,
+    pub checkpoint_revision: u64,
+    #[serde(default)]
+    pub pending_events: Vec<SessionProjectionFrame>,
+    #[serde(default)]
+    pub state: SessionProjectionState,
+}
