 202	    pub(crate) fn open(path: &Path) -> Result<Self> {
 203	        let budget_bytes = std::env::var("OCEAN_SESSION_PROJECTION_JOURNAL_BYTES")
 204	            .ok()
 205	            .and_then(|raw| raw.parse::<u64>().ok())
 206	            .filter(|value| *value > 0)
 207	            .unwrap_or(DEFAULT_JOURNAL_BYTES);
 208	        Self::open_with_config(path, budget_bytes, DEFAULT_LEASE)
