 210	
 211	    fn open_with_config(path: &Path, budget_bytes: u64, lease_duration: Duration) -> Result<Self> {
 212	        if let Some(parent) = path.parent() {
 213	            std::fs::create_dir_all(parent).with_context(|| {
 214	                format!("creating projection DB directory {}", parent.display())
 215	            })?;
 216	        }
 217	        let db = Connection::open(path)
 218	            .with_context(|| format!("opening session projection DB {}", path.display()))?;
 219	        #[cfg(unix)]
 220	        {
 221	            use std::os::unix::fs::PermissionsExt;
 222	            std::fs::set_permissions(path, std::fs::Permissions::from_mode(0o600))
 223	                .with_context(|| format!("securing session projection DB {}", path.display()))?;
 224	        }
 225	        db.execute_batch(
 226	            "PRAGMA journal_mode=WAL; PRAGMA synchronous=NORMAL; PRAGMA foreign_keys=ON;",
 227	        )?;
 228	        db.execute_batch(SCHEMA)?;
 229	        let logical_bytes = db.query_row(
 230	            "SELECT COALESCE(SUM(encoded_bytes),0) FROM session_projection_events",
 231	            [],
 232	            |row| row.get::<_, u64>(0),
 233	        )?;
 234	        let (wakes, _) = broadcast::channel(1024);
 235	        Ok(Self {
 236	            db: Arc::new(Mutex::new(db)),
 237	            epoch: Arc::from(Uuid::new_v4().to_string()),
 238	            wakes,
 239	            leases: Arc::new(Mutex::new(HashMap::new())),
 240	            faults: Arc::new(Mutex::new(HashSet::new())),
 241	            logical_bytes: Arc::new(AtomicU64::new(logical_bytes)),
 242	            budget_bytes,
 243	            lease_duration,
 244	        })
 245	    }
