 298	    fn append(
 299	        &self,
 300	        session_id: &str,
 301	        source: SessionProjectionSource,
 302	        event: Value,
 303	        fold: impl FnOnce(&mut FoldedState, &Value),
 304	    ) -> Result<ProjectionCursor> {
 305	        let event_json = serde_json::to_string(&event)?;
 306	        let created_ms = now_ms();
 307	        let mut db = self.db.lock().unwrap_or_else(|poison| poison.into_inner());
 308	        let tx = db.transaction()?;
 309	        let (latest, checkpoint_seq, checkpoint_revision, state_json) = load_row(
 310	            &tx,
 311	            &self.epoch,
 312	            session_id,
 313	        )?
 314	        .unwrap_or((0, 0, 0, serde_json::to_string(&FoldedState::default())?));
 315	        let seq = latest
 316	            .checked_add(1)
 317	            .context("session projection cursor exhausted")?;
 318	        let mut state: FoldedState = serde_json::from_str(&state_json)?;
 319	        fold(&mut state, &event);
 320	        let state_json = serde_json::to_string(&state)?;
 321	        tx.execute(
 322	            "INSERT INTO session_projection_events(epoch,session_id,seq,source,event_json,encoded_bytes,created_ms) VALUES(?1,?2,?3,?4,?5,?6,?7)",
 323	            params![&*self.epoch, session_id, seq, source_name(source), event_json, event_json.len() as u64, created_ms],
 324	        )?;
 325	        tx.execute(
 326	            "INSERT INTO session_projection_sessions(epoch,session_id,latest_seq,checkpoint_seq,checkpoint_revision,state_json) VALUES(?1,?2,?3,?4,?5,?6) ON CONFLICT(epoch,session_id) DO UPDATE SET latest_seq=excluded.latest_seq,state_json=excluded.state_json",
 327	            params![&*self.epoch, session_id, seq, checkpoint_seq, checkpoint_revision, state_json],
 328	        )?;
 329	        tx.commit()?;
 330	        drop(db);
 331	        self.logical_bytes
 332	            .fetch_add(event_json.len() as u64, Ordering::Relaxed);
 333	        let cursor = ProjectionCursor::new(&self.epoch, session_id, seq);
 334	        let _ = self.wakes.send(session_id.to_string());
 335	        // Ordinary appends only trigger pressure compaction; age-based
 336	        // checkpoint compaction runs when a persistence boundary advances.
 337	        if self.logical_bytes.load(Ordering::Relaxed) > self.budget_bytes {
 338	            self.compact(true)?;
 339	        }
 340	        Ok(cursor)
 341	    }
