 343	    pub(crate) fn checkpoint(&self, session_id: &str, revision: u64) -> Result<()> {
 344	        let mut db = self.db.lock().unwrap_or_else(|poison| poison.into_inner());
 345	        let tx = db.transaction()?;
 346	        let row = load_row(&tx, &self.epoch, session_id)?;
 347	        let (latest, checkpoint_seq, checkpoint_revision, state_json) =
 348	            row.unwrap_or((0, 0, 0, serde_json::to_string(&FoldedState::default())?));
 349	        if revision < checkpoint_revision {
 350	            anyhow::bail!("session projection checkpoint revision regressed");
 351	        }
 352	        let next_checkpoint_seq = if revision == checkpoint_revision {
 353	            checkpoint_seq
 354	        } else {
 355	            latest
 356	        };
 357	        tx.execute(
 358	            "INSERT INTO session_projection_sessions(epoch,session_id,latest_seq,checkpoint_seq,checkpoint_revision,state_json) VALUES(?1,?2,?3,?4,?5,?6) ON CONFLICT(epoch,session_id) DO UPDATE SET checkpoint_seq=excluded.checkpoint_seq,checkpoint_revision=excluded.checkpoint_revision",
 359	            params![&*self.epoch, session_id, latest, next_checkpoint_seq, revision, state_json],
 360	        )?;
 361	        tx.commit()?;
 362	        drop(db);
 363	        self.compact(false)
 364	    }
