5208	async fn session(
5209	    State(state): State<AppState>,
5210	    Path(session_id): Path<SessionId>,
5211	) -> (StatusCode, Json<SessionResponse>) {
5212	    match state.runtime.session_detail(session_id) {
5213	        Ok(mut session) => {
5214	            // A persistence rename and its internal checkpoint cross an async
5215	            // bridge. Bound the alignment wait; never return a cursor for a
5216	            // different file revision. Legacy clients still receive the normal
5217	            // session body if the projection is momentarily unavailable.
5218	            let mut projection = None;
5219	            if let Some(store) = state.agent_events.projection() {
5220	                for attempt in 0..=20 {
5221	                    match store.snapshot(&session_id.to_string(), session.persistence_revision) {
5222	                        Ok(snapshot) => {
5223	                            projection = Some(snapshot);
5224	                            break;
5225	                        }
5226	                        Err(session_projection::ProjectionReset::RevisionMismatch)
5227	                            if attempt < 20 =>
5228	                        {
5229	                            tokio::time::sleep(std::time::Duration::from_millis(5)).await;
5230	                            match state.runtime.session_detail(session_id) {
5231	                                Ok(refreshed) => session = refreshed,
5232	                                Err(_) => break,
5233	                            }
5234	                        }
5235	                        Err(reset) => {
5236	                            tracing::warn!(%session_id, reason = reset.reason(), "session projection snapshot unavailable");
5237	                            break;
5238	                        }
5239	                    }
5240	                }
5241	            }
5242	            enrich_session_detail(&state, &mut session).await;
5243	            (
5244	                StatusCode::OK,
5245	                Json(SessionResponse {
5246	                    ok: true,
5247	                    session: Some(session),
5248	                    projection,
5249	                    error: None,
5250	                }),
5251	            )
5252	        }
5253	        Err(error) if is_not_found(&error) => (
5254	            StatusCode::NOT_FOUND,
5255	            Json(SessionResponse {
5256	                ok: false,
5257	                session: None,
5258	                projection: None,
5259	                error: Some("session not found".into()),
5260	            }),
5261	        ),
5262	        Err(error) => {
5263	            tracing::warn!(%session_id, error = %error, "failed to read session detail");
5264	            (
5265	                StatusCode::INTERNAL_SERVER_ERROR,
5266	                Json(SessionResponse {
5267	                    ok: false,
5268	                    session: None,
5269	                    projection: None,
5270	                    error: Some("session could not be read".into()),
5271	                }),
5272	            )
5273	        }
5274	    }
5275	}
