6858	struct SessionProjectionEventsQuery {
6859	    session_id: AgentSessionId,
6860	    after_cursor: String,
6861	}
6862	
6863	/// Durable session-projection SSE tail. SQLite is authoritative; the broadcast
6864	/// receiver is only a wake hint. Subscribe-before-page plus paging on lag closes
6865	/// the snapshot/live seam without depending on the legacy UUID replay ring.
6866	async fn session_projection_events(
6867	    State(state): State<AppState>,
6868	    Query(query): Query<SessionProjectionEventsQuery>,
6869	) -> Sse<impl Stream<Item = Result<Event, Infallible>>> {
6870	    let (tx, rx) = mpsc::channel(64);
6871	    let shutdown = state.shutdown.clone();
6872	    let session_id = query.session_id.to_string();
6873	    let mut cursor = query.after_cursor;
6874	    let projection = state.agent_events.projection();
6875	
6876	    tokio::spawn(async move {
6877	        let Some(store) = projection else {
6878	            let data = json!({ "type": "projection_reset", "reason": "projection_unavailable" })
6879	                .to_string();
6880	            let _ = tx
6881	                .send(Ok(Event::default().event("projection_reset").data(data)))
6882	                .await;
6883	            return;
6884	        };
6885	
6886	        // Register before the first durable page. Any append racing the query is
6887	        // either visible in SQLite or leaves a buffered wake that causes re-page.
6888	        let mut wakes = store.subscribe();
6889	        loop {
6890	            match store.page_after(&session_id, &cursor) {
6891	                Ok(frames) if !frames.is_empty() => {
6892	                    for frame in frames {
6893	                        cursor = frame.cursor.clone();
6894	                        let data = serde_json::to_string(&frame).unwrap_or_else(|_| {
6895	                            json!({ "type": "projection_reset", "reason": "serialize_failed" })
6896	                                .to_string()
6897	                        });
6898	                        if tx
6899	                            .send(Ok(Event::default()
6900	                                .id(frame.cursor)
6901	                                .event("session_projection")
6902	                                .data(data)))
6903	                            .await
6904	                            .is_err()
6905	                        {
6906	                            return;
6907	                        }
6908	                    }
6909	                    continue;
6910	                }
6911	                Ok(_) => {}
6912	                Err(reset) => {
6913	                    let data = json!({
6914	                        "type": "projection_reset",
6915	                        "reason": reset.reason(),
6916	                    })
6917	                    .to_string();
