 366	    pub(crate) fn snapshot(
 367	        &self,
 368	        session_id: &str,
 369	        file_revision: u64,
 370	    ) -> std::result::Result<SessionProjection, ProjectionReset> {
 371	        if self.is_faulted(session_id) {
 372	            return Err(ProjectionReset::Faulted);
 373	        }
 374	        let mut db = self.db.lock().unwrap_or_else(|poison| poison.into_inner());
 375	        let tx = db.transaction().map_err(|_| ProjectionReset::Faulted)?;
 376	        let row = load_row(&tx, &self.epoch, session_id).map_err(|_| ProjectionReset::Faulted)?;
 377	        let (latest, mut checkpoint_seq, mut checkpoint_revision, state_json) = row.unwrap_or((
 378	            0,
 379	            0,
 380	            file_revision,
 380	            file_revision,
 381	            serde_json::to_string(&FoldedState::default()).map_err(|_| ProjectionReset::Faulted)?,
 382	        ));
 383	        let state: FoldedState =
 384	            serde_json::from_str(&state_json).map_err(|_| ProjectionReset::Faulted)?;
 385	        if file_revision != checkpoint_revision {
 386	            if file_revision > checkpoint_revision && state.active_turn.is_none() {
 387	                checkpoint_revision = file_revision;
 388	                checkpoint_seq = latest;
 389	            } else {
 390	                return Err(ProjectionReset::RevisionMismatch);
 391	            }
 392	        }
 393	        tx.execute(
 394	            "INSERT INTO session_projection_sessions(epoch,session_id,latest_seq,checkpoint_seq,checkpoint_revision,state_json) VALUES(?1,?2,?3,?4,?5,?6) ON CONFLICT(epoch,session_id) DO UPDATE SET checkpoint_seq=excluded.checkpoint_seq,checkpoint_revision=excluded.checkpoint_revision",
 395	            params![&*self.epoch, session_id, latest, checkpoint_seq, checkpoint_revision, state_json],
 396	        )
 397	        .map_err(|_| ProjectionReset::Faulted)?;
 398	        let pending = query_frames(&tx, &self.epoch, session_id, checkpoint_seq, latest)
 399	            .map_err(|_| ProjectionReset::Faulted)?;
 400	        tx.commit().map_err(|_| ProjectionReset::Faulted)?;
 401	        drop(db);
 402	        self.renew_lease(session_id, latest);
 403	        Ok(SessionProjection {
 404	            version: 1,
 405	            cursor: ProjectionCursor::new(&self.epoch, session_id, latest).to_string(),
 406	            checkpoint_revision,
 407	            pending_events: pending,
 408	            state: state.wire(),
 409	        })
 410	    }
