 412	    pub(crate) fn page_after(
 413	        &self,
 414	        session_id: &str,
 415	        raw_cursor: &str,
 416	    ) -> std::result::Result<Vec<SessionProjectionFrame>, ProjectionReset> {
 417	        if self.is_faulted(session_id) {
 418	            return Err(ProjectionReset::Faulted);
 419	        }
 420	        let cursor = ProjectionCursor::parse(raw_cursor)?;
 421	        if cursor.epoch.as_str() != self.epoch.as_ref() {
 422	            return Err(ProjectionReset::WrongEpoch);
 423	        }
 424	        if cursor.session_hash != session_hash(session_id) {
 425	            return Err(ProjectionReset::WrongSession);
 426	        }
 427	        let db = self.db.lock().unwrap_or_else(|poison| poison.into_inner());
 428	        let Some((latest, _, _, _)) =
 429	            load_row(&db, &self.epoch, session_id).map_err(|_| ProjectionReset::Faulted)?
 430	        else {
 431	            if cursor.seq == 0 {
 432	                return Ok(Vec::new());
 433	            }
 434	            return Err(ProjectionReset::Future);
 435	        };
 436	        if cursor.seq > latest {
 437	            return Err(ProjectionReset::Future);
 438	        }
 439	        let earliest: Option<u64> = db
 440	            .query_row(
 441	                "SELECT MIN(seq) FROM session_projection_events WHERE epoch=?1 AND session_id=?2",
 442	                params![&*self.epoch, session_id],
 443	                |row| row.get(0),
 444	            )
 445	            .optional()
 446	            .map_err(|_| ProjectionReset::Faulted)?
 447	            .flatten();
 448	        if cursor.seq < latest && earliest.is_none_or(|first| cursor.seq.saturating_add(1) < first)
 449	        {
 450	            return Err(ProjectionReset::Retention);
 451	        }
 452	        let through = cursor.seq.saturating_add(PAGE_LIMIT as u64);
 453	        let frames = query_frames(
 454	            &db,
 455	            &self.epoch,
 456	            session_id,
 457	            cursor.seq,
 458	            through.min(latest),
 459	        )
 460	        .map_err(|_| ProjectionReset::Faulted)?;
 461	        drop(db);
 462	        let sent = frames
 463	            .last()
 464	            .and_then(|frame| ProjectionCursor::parse(&frame.cursor).ok())
 465	            .map(|cursor| cursor.seq)
 466	            .unwrap_or(cursor.seq);
 467	        self.renew_lease(session_id, sent);
 468	        Ok(frames)
 469	    }
