 487	    fn renew_lease(&self, session_id: &str, min_seq: u64) {
 488	        self.leases
 489	            .lock()
 490	            .unwrap_or_else(|poison| poison.into_inner())
 491	            .entry(session_id.to_string())
 492	            .or_default()
 493	            .push(Lease {
 494	                min_seq,
 495	                expires: Instant::now() + self.lease_duration,
 496	            });
