 498	
 499	    fn compact(&self, pressure_only: bool) -> Result<()> {
 500	        let now = Instant::now();
 501	        let leases = {
 502	            let mut leases = self
 503	                .leases
 504	                .lock()
 505	                .unwrap_or_else(|poison| poison.into_inner());
 506	            leases.retain(|_, session_leases| {
 507	                session_leases.retain(|lease| lease.expires > now);
 508	                !session_leases.is_empty()
 509	            });
 510	            leases.clone()
 511	        };
 512	        let cutoff_ms = now_ms().saturating_sub(self.lease_duration.as_millis() as i64);
 513	        let pressure = self.logical_bytes.load(Ordering::Relaxed) > self.budget_bytes;
 514	        if pressure_only && !pressure {
 515	            return Ok(());
 516	        }
 517	        let mut db = self.db.lock().unwrap_or_else(|poison| poison.into_inner());
 518	        let rows = {
 519	            let mut stmt = db.prepare(
 520	                "SELECT session_id,checkpoint_seq FROM session_projection_sessions WHERE epoch=?1",
 521	            )?;
 522	            let collected = stmt
 523	                .query_map([&*self.epoch], |row| {
 524	                    Ok((row.get::<_, String>(0)?, row.get::<_, u64>(1)?))
 525	                })?
 526	                .collect::<std::result::Result<Vec<_>, _>>()?;
 527	            collected
 528	        };
 529	        let tx = db.transaction()?;
 530	        for (session_id, checkpoint_seq) in rows {
 531	            let protected = leases
 532	                .get(&session_id)
 533	                .and_then(|session_leases| session_leases.iter().map(|lease| lease.min_seq).min())
 534	                .unwrap_or(checkpoint_seq);
 535	            let through = checkpoint_seq.min(protected);
 536	            if pressure {
 537	                tx.execute(
 538	                    "DELETE FROM session_projection_events WHERE epoch=?1 AND session_id=?2 AND seq<=?3",
 539	                    params![&*self.epoch, session_id, through],
 540	                )?;
 541	            } else {
 542	                tx.execute(
 543	                    "DELETE FROM session_projection_events WHERE epoch=?1 AND session_id=?2 AND seq<=?3 AND created_ms<=?4",
 544	                    params![&*self.epoch, session_id, through, cutoff_ms],
 545	                )?;
 546	            }
 547	        }
 548	        if pressure {
 549	            tx.execute(
 550	                "DELETE FROM session_projection_events WHERE epoch<>?1",
 551	                [&*self.epoch],
 552	            )?;
 553	        }
 554	        tx.commit()?;
 555	        let remaining = db.query_row(
 556	            "SELECT COALESCE(SUM(encoded_bytes),0) FROM session_projection_events",
 557	            [],
 558	            |row| row.get::<_, u64>(0),
 559	        )?;
 560	        self.logical_bytes.store(remaining, Ordering::Relaxed);
 561	        Ok(())
 562	    }
 563	}
